package handlers.bypass.npc;

import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.entity.actor.Npc;
import org.l2jmobius.gameserver.entity.actor.Player;
import org.l2jmobius.gameserver.handler.IBypassHandler;
import org.l2jmobius.gameserver.mechanics.events.EventDispatcher;
import org.l2jmobius.gameserver.mechanics.events.EventType;
import org.l2jmobius.gameserver.mechanics.events.holders.actor.npc.OnNpcFirstTalk;

/**
 * Handles the logic for chat links triggered by {@code Npc} interactions.<br>
 * This class processes specific bypass commands when a player interacts with an NPC.<br>
 * It ensures that linked content is correctly delivered to the {@code Player}.
 */
public class ChatLink implements IBypassHandler
{
	private static final String[] COMMANDS =
	{
		"Chat"
	};
	
	/**
	 * Handles the execution of a specific command for an NPC.<br>
	 * This method checks if the target is an {@code Npc}.<br>
	 * It triggers a first talk event or opens a chat window based on the input.
	 * @param command The raw command string provided by the player.
	 * @param player The {@code Player} who sent the command.
	 * @param target The {@code Creature} being interacted with.
	 * @return Always returns {@code false}.
	 */
	@Override
	public boolean onCommand(String command, Player player, Creature target)
	{
		if (!target.isNpc())
		{
			return false;
		}
		
		int val = 0;
		try
		{
			val = Integer.parseInt(command.substring(5));
		}
		catch (Exception e)
		{
			// Handled above.
		}
		
		final Npc npc = target.asNpc();
		if ((val == 0) && npc.hasListener(EventType.ON_NPC_FIRST_TALK))
		{
			EventDispatcher.getInstance().notifyEventAsync(new OnNpcFirstTalk(npc, player), npc);
		}
		else
		{
			npc.showChatWindow(player, val);
		}
		
		return false;
	}
	
	/**
	 * Retrieves the list of valid commands for this handler.<br>
	 * This method returns the {@code COMMANDS} array.
	 * @return an array of {@code String} containing all supported commands.
	 */
	@Override
	public String[] getCommandList()
	{
		return COMMANDS;
	}
}
